#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cstdint>
#include <cstring>
#include "../distort-cuda/distort.cu"
static_assert(sizeof(Properties)==40&&sizeof(uchar3)==3,"SharedABI");
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
template<class T>std::vector<T>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=f.tellg();f.seekg(0);std::vector<T>v(n/sizeof(T));f.read((char*)v.data(),n);return v;}
struct S{int w,h,mode,reps;uchar*a,*b;Properties*prop;std::vector<uchar>raw;std::vector<Properties>ph;};
Properties actualprop(int w,int h,float k){Properties q;q.K=k;q.centerX=w/2;q.centerY=h/2;q.width=w;q.height=h;q.thresh=1.f;q.xshift=calc_shift(0,q.centerX-1,q.centerX,q.K,q.thresh);float cx=w-q.centerX;float x2=calc_shift(0,cx-1,cx,q.K,q.thresh);q.yshift=calc_shift(0,q.centerY-1,q.centerY,q.K,q.thresh);float cy=h-q.centerY;float y2=calc_shift(0,cy-1,cy,q.K,q.thresh);q.xscale=(w-q.xshift-x2)/w;q.yscale=(h-q.yshift-y2)/h;return q;}
int main(){auto fixture=load<uint32_t>(DR_FIXTURE);auto lo=load<uchar>(DR_LOWER),hi=load<uchar>(DR_UPPER);std::vector<S>states;size_t off=0;Properties guard;uint32_t gb[10];for(auto&x:gb)x=0xdeadbeef;memcpy(&guard,gb,40);while(off<fixture.size()){S s;s.w=fixture[off];s.h=fixture[off+1];s.mode=fixture[off+2];s.reps=fixture[off+3];int n=s.w*s.h;Properties q;memcpy(&q,fixture.data()+off+4,40);auto fromsource=actualprop(s.w,s.h,q.K);if(memcmp(&q,&fromsource,40)){fprintf(stderr,"NativePropertyPreprocessingBitsDisagree\n");return 6;}s.ph={guard,q,guard};s.raw.push_back(165);for(int i=0;i<3*n;i++)s.raw.push_back(uchar(fixture[off+14+i]));s.raw.push_back(165);off+=14+3*n;ck(cudaMalloc(&s.a,3*n+2));ck(cudaMalloc(&s.b,3*n+2));ck(cudaMalloc(&s.prop,120));ck(cudaMemcpy(s.a,s.raw.data(),3*n+2,cudaMemcpyHostToDevice));ck(cudaMemcpy(s.prop,s.ph.data(),120,cudaMemcpyHostToDevice));states.push_back(s);}
auto run=[&](S&s){int n=s.w*s.h;ck(cudaMemset(s.b,165,3*n+2));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<s.reps;rep++)barrel_distort<<<dim3(s.w/16+1,s.h/16+1),dim3(16,16)>>>((uchar3*)(s.a+1),(uchar3*)(s.b+1),s.prop+1);ck(cudaGetLastError());ck(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/s.reps;};for(auto&s:states)run(s);for(int trial=1;trial<=5;trial++){auto out=fixture;size_t oi=0;double elapsed=0;bool ok=true;for(auto&s:states){elapsed+=run(s);int n=s.w*s.h;std::vector<uchar>got(3*n+2),back(3*n+2);std::vector<Properties>pb(3);ck(cudaMemcpy(got.data(),s.b,got.size(),cudaMemcpyDeviceToHost));ck(cudaMemcpy(back.data(),s.a,back.size(),cudaMemcpyDeviceToHost));ck(cudaMemcpy(pb.data(),s.prop,120,cudaMemcpyDeviceToHost));ok&=back==s.raw&&memcmp(pb.data(),s.ph.data(),120)==0&&got.front()==165&&got.back()==165;for(int i=1;i<=3*n;i++){ok&=lo[oi]<=got[i]&&got[i]<=hi[oi];oi++;out.push_back(uint32_t(got[i]));}out.insert(out.end(),{uint32_t(back.front()),uint32_t(back.back()),uint32_t(got.front()),uint32_t(got.back())});uint32_t bits[10];for(int q:{0,2}){memcpy(bits,&pb[q],40);out.insert(out.end(),bits,bits+10);}}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"timing_region\":\"sum4_source_barrel_5repeat_means_globalproperties_complete\",\"jit_excluded\":true,\"internal_repeats\":5,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",out.size(),path.c_str(),out.size());if(!ok)return 3;}for(auto&s:states){ck(cudaFree(s.a));ck(cudaFree(s.b));ck(cudaFree(s.prop));}}
